export const PROJECT_KEY_MAX_LENGTH = 4;

/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */
export function projectKeyFromName(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  const letters =
    words.length >= 2
      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
      : (words[0] ?? "task").slice(0, 3);
  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, PROJECT_KEY_MAX_LENGTH) || "TASK";
}

/**
 * Makes a project key collide with nothing in `taken` by appending a number,
 * the way `uniqueSlug` does for addresses. The suffix is kept within
 * `PROJECT_KEY_MAX_LENGTH` characters, so `WEBS` becomes `WEB2`, not `WEBS2`.
 */
export function uniqueProjectKey(input: string, taken: Iterable<string>): string {
  const base = input.slice(0, PROJECT_KEY_MAX_LENGTH);
  const used = new Set(taken);
  if (!used.has(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const digits = String(suffix);
    const candidate = `${base.slice(0, PROJECT_KEY_MAX_LENGTH - digits.length)}${digits}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique key suffixes");
}

