32	/**
33	 * Creates a project once the plan still has room for one. The key is derived
34	 * from the name when the caller left it blank, so the issue numbering scheme
35	 * (`TF-12`) is never invented at the call site.
36	 */
37	export async function createProject(
38	  actor: Actor,
39	  input: CreateProjectInput,
40	): Promise<Project> {
41	  assertOrgScope(actor, input.orgId);
42	  assertCan(actor, "project:create", orgResource(input.orgId));
43	
44	  const org = requireFound(
45	    await orgRepo.findOrgById(input.orgId),
46	    "Organization",
47	    input.orgId,
48	  );
