60	    ...input,
61	    slug,
62	    key: input.key || projectKeyFromName(input.name),
63	  });
64	
65	  await emit("project.created", {
66	    ...actorEnvelope(actor),
67	    projectId: project.id,
68	    name: project.name,
69	    slug: project.slug,
70	  });
71	
72	  return project;
73	}
74	
75	export async function updateProject(
76	  actor: Actor,
77	  input: UpdateProjectInput,
78	): Promise<Project> {
